flow.typescript:
// D11 · Part 0~7 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d11_flow.ts
//   전사 정제 → PCM 읽기 → 목록표 → 품질 필터 → 화자 단위 분할 → Whisper 입력(80 × 3000) 순서를 작게 한 번에 돌린다
//   흉내 낸 부분: 사람 목소리 대신 사인파, 멜 대신 80개 대역 에너지, 진짜 토크나이저 대신 UTF-8 바이트
const SR = 16000;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function cleanKspon(text: string, mode: string = "spelling"): string {
  let s = text.replace(/\(([^)]*)\)\/\(([^)]*)\)/g, (_m, a: string, b: string) => (mode === "phonetic" ? b : a));
  s = s.replace(/[a-z]\//g, "");
  s = s.replaceAll("+", "").replaceAll("*", "").replaceAll("/", "");
  return s.replace(/\s+/g, " ").trim();
}

function tone(sec: number, f: number): Float32Array {
  const y = new Float32Array(Math.floor(sec * SR));
  for (let i = 0; i < y.length; i++) y[i] = 0.3 * Math.sin((2 * Math.PI * f * i) / SR);
  return y;
}

type Row = { text: string; speaker: string; duration: number; cps: number; y: Float32Array };

// 1) 합성 데이터: [전사, 화자, 소리 길이 초]
const RAW: [string, string, number][] = [
  ["o/ 그럼 (3시)/(세 시)에 회의를 시작할까요?", "s1", 3.0], ["b/ 어/ 저는 (10월)/(시월)에 발표를 해요.", "s1", 3.5],
  ["음/ 그+ 그 자료는 n/ 아직 못 봤어요.", "s2", 3.2], ["네.", "s2", 12.0], ["아/ 그건 * 잘 모르겠는데요.", "s3", 3.0],
  ["오늘 회의는 여기까지 하겠습니다.", "s3", 0.4], ["다음 주까지 자료를 정리해 주세요.", "s4", 4.0], ["일정은 그대로 갑니다.", "s4", 2.5],
];

// 2) 정제 + PCM(16-bit, 머리말 없음) 왕복 + 목록표
const rows: Row[] = RAW.map(([raw, spk, sec], i) => {
  const src = tone(sec, 200 + 40 * i);
  const pcm = Buffer.alloc(src.length * 2); // 파일에 쓰는 바이트
  src.forEach((v, k) => pcm.writeInt16LE(Math.round(v * 32767), k * 2));
  const y = new Float32Array(pcm.length / 2); // 읽을 때는 16비트 정수라고 알려 줘야 함
  for (let k = 0; k < y.length; k++) y[k] = pcm.readInt16LE(k * 2) / 32768;
  const text = cleanKspon(raw, "phonetic");
  const nChars = text.replaceAll(" ", "").length;
  return { text, speaker: spk, duration: y.length / SR, cps: nChars / (y.length / SR), y };
});
console.log(`목록표 ${rows.length}행, 첫 문장: ${rows[0].text}`);

// 3) 품질 필터
function reason(r: Row): string {
  if (!r.text) return "빈 전사";
  if (r.duration < 1.0) return "너무 짧음";
  if (r.duration > 30) return "너무 김";
  if (r.cps > 12) return "너무 빠름";
  if (r.cps < 2) return "너무 느림";
  return "";
}
const okRows = rows.filter((r) => !reason(r));
console.log("버린 샘플:", rows.filter((r) => reason(r)).map((r) => `${r.text}(${reason(r)})`).join(", "));

// 4) 화자 단위 분할 (같은 화자가 train · test에 걸치면 안 됨)
const speakers = [...new Set(okRows.map((r) => r.speaker))].sort();
const testSpk = new Set(speakers.slice(-1));
const train = okRows.filter((r) => !testSpk.has(r.speaker));
const test = okRows.filter((r) => testSpk.has(r.speaker));
const overlap = [...new Set(train.map((r) => r.speaker))].filter((s) => test.some((r) => r.speaker === s));
console.log(`train ${train.length}개 · test ${test.length}개 · 겹치는 화자: ${overlap.length ? overlap.join(",") : "없음"}`);

// 5) Whisper 입력: 소리 → 80 × 3000 특징, 글자 → 토큰 번호
function features(y: Float32Array): Float32Array[] {
  const nFft = 400, hop = 160;
  const n = 1 + Math.floor((y.length - nFft) / hop);
  const cosT = Array.from({ length: 201 }, (_, k) => Float64Array.from({ length: nFft }, (_, t) => Math.cos((2 * Math.PI * k * t) / nFft)));
  const sinT = Array.from({ length: 201 }, (_, k) => Float64Array.from({ length: nFft }, (_, t) => Math.sin((2 * Math.PI * k * t) / nFft)));
  const out = Array.from({ length: 80 }, () => new Float32Array(3000));
  let floor = Infinity;
  const feat: number[][] = [];
  for (let i = 0; i < Math.min(n, 3000); i++) {
    const seg = Float64Array.from({ length: nFft }, (_, t) => y[i * hop + t] * (0.5 - 0.5 * Math.cos((2 * Math.PI * t) / nFft)));
    const bands = new Array(80).fill(0);
    for (let k = 0; k < 201; k++) {
      let re = 0, im = 0;
      for (let t = 0; t < nFft; t++) { re += seg[t] * cosT[k][t]; im -= seg[t] * sinT[k][t]; }
      bands[Math.min(79, Math.floor((k * 80) / 201))] += re * re + im * im; // 멜 대신 80개 대역 에너지로 흉내
    }
    const col = bands.map((b: number) => Math.log10(Math.max(b, 1e-10)));
    floor = Math.min(floor, ...col);
    feat.push(col);
  }
  for (const row of out) row.fill(floor); // 30초 창에 맞춰 뒤를 채움
  feat.forEach((col, i) => col.forEach((v, m) => { out[m][i] = v; }));
  return out;
}

const SOT = 50258, KO = 50264, TRANSCRIBE = 50359, NOTS = 50363, EOT = 50257; // Whisper 특수 토큰 번호
const sample = train[0];
const f = features(sample.y);
const labels = [SOT, KO, TRANSCRIBE, NOTS, ...Buffer.from(sample.text, "utf-8"), EOT];
console.log(`input_features 모양: (${f.length}, ${f[0].length}) · labels 길이: ${labels.length}`);
check(overlap.length === 0 && f.length === 80 && f[0].length === 3000 && okRows.length === 6 && labels.length <= 448,
  "화자 겹침 없음 · 특징 80 × 3000 · 걸러진 뒤 6개 · labels ≤ 448 이어야 해요.");

landscape.typescript:
// D11 · Part 1 · 한국어 음성 데이터셋 지도 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d11_landscape.ts
//   데이터셋 비교표를 만들고, 서비스에 맞는 데이터를 조건으로 골라 본다
type Dataset = { name: string; style: string; hours: number; speakers: number; license: string; get: string; redistribute: boolean };

const DATASETS: Dataset[] = [
  { name: "Zeroth-Korean", style: "낭독", hours: 51.6, speakers: 105, license: "CC BY 4.0", get: "바로", redistribute: true },
  { name: "KsponSpeech", style: "대화", hours: 1000, speakers: 2000, license: "AIHub 약관", get: "신청·승인", redistribute: false },
  { name: "AIHub 분야별 음성", style: "분야별", hours: 500, speakers: 1000, license: "AIHub 약관", get: "신청·승인", redistribute: false },
  { name: "Common Voice ko", style: "낭독", hours: 10, speakers: 500, license: "CC0", get: "바로", redistribute: true },
  { name: "FLEURS ko", style: "낭독", hours: 10, speakers: 20, license: "CC BY 4.0", get: "바로", redistribute: true },
]; // 규모는 강의용 어림값이에요(Zeroth만 실제 수치). 신청 전에 각 데이터셋 페이지에서 확인하세요.

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function pick(styles: string[], needNow: boolean): string[] {
  // 서비스 말투와 맞고(필요하면 신청 없이 바로 받을 수 있는) 데이터셋 이름
  return DATASETS.filter((d) => styles.includes(d.style) && (d.get === "바로" || !needNow)).map((d) => d.name);
}

console.log("이름".padEnd(20) + "말투".padEnd(8) + "시간".padStart(8) + "화자".padStart(7) + "  라이선스 · 받는 법");
for (const d of DATASETS) {
  console.log(d.name.padEnd(20) + d.style.padEnd(8) + d.hours.toFixed(1).padStart(8) + String(d.speakers).padStart(7) + `  ${d.license} · ${d.get}`);
}

const zeroth = DATASETS[0];
console.log(`\nZeroth 화자 1명당 평균 ${((zeroth.hours * 60) / zeroth.speakers).toFixed(1)}분`);
const callCenter = pick(["대화", "분야별"], false); // 콜센터: 말투가 비슷한 데이터가 먼저
const quickLab = pick(["낭독"], true); // 실습 · 빠른 실험: 바로 받는 데이터
console.log("콜센터 후보:", callCenter, "· 빠른 실험 후보:", quickLab);
check(!callCenter.includes("Zeroth-Korean") && quickLab[0] === "Zeroth-Korean" && DATASETS.filter((d) => d.get !== "바로").every((d) => !d.redistribute),
  "콜센터는 대화·분야별 데이터, 실습은 바로 받는 Zeroth 가 먼저예요.");

hfstream.typescript:
// D11 · Part 2 · 다운로드 vs 스트리밍 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d11_hfstream.ts   (Hugging Face 대신 코드 안의 모의 데이터셋 · 인터넷 불필요)
//   전부 받은 뒤 시작(다운로드) vs 필요한 만큼만 읽기(스트리밍): 읽은 바이트를 세어 비교하고, 바이트 → 소리로 읽어 본다
const SR = 16000;
const N_EXAMPLES = 2000, SHARD = 100; // 샘플 2000개, 100개씩 한 조각(shard)

type Example = { audio: { bytes: Buffer }; text: string; speaker_id: number };

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function wavBytes(samples: Int16Array, sr: number): Buffer {
  const data = Buffer.alloc(samples.length * 2);
  samples.forEach((v, i) => data.writeInt16LE(v, i * 2));
  const h = Buffer.alloc(44);
  h.write("RIFF", 0); h.writeUInt32LE(36 + data.length, 4); h.write("WAVEfmt ", 8); h.writeUInt32LE(16, 16);
  h.writeUInt16LE(1, 20); h.writeUInt16LE(1, 22); h.writeUInt32LE(sr, 24); h.writeUInt32LE(sr * 2, 28);
  h.writeUInt16LE(2, 32); h.writeUInt16LE(16, 34); h.write("data", 36); h.writeUInt32LE(data.length, 40);
  return Buffer.concat([h, data]);
}

function makeExample(i: number): Example {
  // 모의 샘플: Hugging Face가 주는 { audio: { bytes: WAV 바이트 }, text } 와 같은 모양
  const y = new Int16Array(SR / 4);
  for (let t = 0; t < y.length; t++) y[t] = Math.round(0.3 * 32767 * Math.sin((2 * Math.PI * (200 + (i % 50)) * t) / SR));
  return { audio: { bytes: wavBytes(y, SR) }, text: `문장 ${i}`, speaker_id: i % 10 };
}

let bytesRead = 0;
function* mockDataset(): Generator<Example> {
  for (let start = 0; start < N_EXAMPLES; start += SHARD) {
    const shard = Array.from({ length: SHARD }, (_, k) => makeExample(start + k));
    bytesRead += shard.reduce((s, e) => s + e.audio.bytes.length, 0); // 조각 하나를 읽을 때마다 바이트가 늘어남
    yield* shard;
  }
}

// 다운로드: 전부 읽은 뒤에야 첫 샘플
bytesRead = 0;
const allRows = [...mockDataset()];
const downloadBytes = bytesRead;

// 스트리밍: 처음 3개만
bytesRead = 0;
const first3: Example[] = [];
for (const ex of mockDataset()) {
  first3.push(ex);
  if (first3.length === 3) break;
}
const streamBytes = bytesRead;
console.log(`다운로드 ${(downloadBytes / 1e6).toFixed(1)} MB · 스트리밍(3개) ${(streamBytes / 1e6).toFixed(2)} MB`);

const b = first3[0].audio.bytes; // 빈칸 실습 2: 바이트를 소리로 (WAV 머리말에서 주파수 · 길이를 읽음)
const sr = b.readUInt32LE(24);
const nSamples = b.readUInt32LE(40) / 2;
console.log(`sr = ${sr}, 길이 ${(nSamples / sr).toFixed(2)}초, 화자 ${first3[0].speaker_id}`);
check(allRows.length === N_EXAMPLES && first3.length === 3 && streamBytes * 10 < downloadBytes && sr === SR,
  "스트리밍은 조각 하나만 읽어서 다운로드보다 훨씬 적게 읽어야 해요.");

kspon.typescript:
// D11 · Part 3 · KsponSpeech 전사 정제기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d11_kspon.ts
//   (철자)/(발음) 이중 전사, 잡음 태그, 반복 +, 불명확 * 를 정리해서 철자판 · 발음판 두 가지로 만든다
const KSPON_TRN: string[] = [
  "o/ 그럼 (3시)/(세 시)에 회의를 시작할까요?",
  "b/ 어/ 저는 (10월)/(시월)에 발표를 해요.",
  "음/ 그+ 그 자료는 n/ 아직 못 봤어요.",
  "(2시 30분)/(두 시 삼십 분)까지 보내 주세요. u/",
  "아/ 그건 * 잘 모르겠는데요.",
  "(AI)/(에이 아이) 수업은 재밌어요.",
];

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function cleanKspon(text: string, mode: string = "spelling"): string {
  // ① 이중 전사: (철자)/(발음) → 한쪽만
  let s = text.replace(/\(([^)]*)\)\/\(([^)]*)\)/g, (_m, a: string, b: string) => (mode === "phonetic" ? b : a));
  // ② 잡음 태그 지우기: b/ l/ o/ n/ u/ (소문자 + /)
  s = s.replace(/[a-z]\//g, "");
  // ③ 반복 +, 불명확 *, 간투어 표시 / 지우기
  s = s.replaceAll("+", "").replaceAll("*", "").replaceAll("/", "");
  // ④ 공백 정리
  return s.replace(/\s+/g, " ").trim();
}

for (const t of KSPON_TRN.slice(0, 3)) {
  console.log(`원본: ${t}\n  철자: ${cleanKspon(t)}\n  발음: ${cleanKspon(t, "phonetic")}`);
}

const ex = "o/ 그럼 (3시)/(세 시)에 b/ 회의+ 회의를 할까/ 요* 음/";
check(cleanKspon(ex) === "그럼 3시에 회의 회의를 할까 요 음" && cleanKspon(ex, "phonetic") === "그럼 세 시에 회의 회의를 할까 요 음",
  "이중 전사는 철자면 첫 번째 괄호, 발음이면 두 번째 괄호를 남겨야 해요.");

pcm.typescript:
// D11 · Part 3 · PCM 바이트 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d11_pcm.ts   (합성 신호를 임시 폴더에 .pcm으로 써서 다시 읽어요 · 인터넷·마이크 불필요)
//   머리말 없는 16-bit PCM: 바이트 수 ÷ 2 = 샘플 수, 틀린 크기(4바이트)로 읽으면 길이가 절반이 되는 것을 확인한다
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const SR = 16000;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function readPcm(p: string): Float32Array {
  const raw = fs.readFileSync(p);
  const y = new Float32Array(raw.length / 2); // 16비트 정수 = 2바이트씩
  for (let i = 0; i < y.length; i++) y[i] = raw.readInt16LE(i * 2) / 32768;
  return y;
}

const dir = fs.mkdtempSync(path.join(os.tmpdir(), "d11pcm-"));
try {
  const file = path.join(dir, "KsponSpeech_000001.pcm");
  const n = Math.floor(1.5 * SR);
  const sig = new Float64Array(n);
  const raw = Buffer.alloc(n * 2);
  for (let i = 0; i < n; i++) {
    sig[i] = 0.5 * Math.sin((2 * Math.PI * 440 * i) / SR);
    raw.writeInt16LE(Math.round(sig[i] * 32767), i * 2); // 머리말 없이 샘플만 쓴 파일
  }
  fs.writeFileSync(file, raw);
  const size = fs.statSync(file).size;
  const y = readPcm(file);
  const wrongCount = Math.floor(size / 4); // 일부러 틀린 크기(float32 = 4바이트)로 읽으면
  console.log(`파일 크기 ${size.toLocaleString("en-US")} 바이트 → 샘플 ${y.length.toLocaleString("en-US")}개 → ${(y.length / SR).toFixed(2)}초 (16 kHz 가정)`);
  console.log("앞 8개 값:", Array.from(y.slice(0, 8)).map((v) => v.toFixed(4)).join(" "));
  console.log(`4바이트씩 잘못 읽으면 샘플 ${wrongCount.toLocaleString("en-US")}개 (길이가 절반)`);
  let maxErr = 0, maxAbs = 0;
  for (let i = 0; i < n; i++) {
    maxErr = Math.max(maxErr, Math.abs(y[i] - sig[i]));
    maxAbs = Math.max(maxAbs, Math.abs(y[i]));
  }
  check(y.length * 2 === size && maxAbs <= 1.0 && wrongCount * 2 === y.length && maxErr < 1e-3,
    "16비트 정수 = 2바이트씩 읽고 32768로 나누면 -1~1 이에요.");
} finally {
  fs.rmSync(dir, { recursive: true, force: true });
}

manifest.typescript:
// D11 · Part 4 · AIHub 목록표 만들기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d11_manifest.ts   (소리 + JSON 라벨을 임시 폴더에 합성해서 읽어요 · 인터넷 불필요)
//   하위 폴더까지 JSON을 모두 찾고, 소리는 WAV 머리말(44바이트)만 읽어 길이·주파수·채널을 표로 모은다
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function wavBytes(nFrames: number, sr: number, ch: number, f: number): Buffer {
  const data = Buffer.alloc(nFrames * ch * 2);
  for (let i = 0; i < nFrames; i++) {
    const v = Math.round(0.3 * 32767 * Math.sin((2 * Math.PI * f * i) / sr));
    for (let c = 0; c < ch; c++) data.writeInt16LE(v, (i * ch + c) * 2);
  }
  const h = Buffer.alloc(44);
  h.write("RIFF", 0); h.writeUInt32LE(36 + data.length, 4); h.write("WAVEfmt ", 8); h.writeUInt32LE(16, 16);
  h.writeUInt16LE(1, 20); h.writeUInt16LE(ch, 22); h.writeUInt32LE(sr, 24); h.writeUInt32LE(sr * ch * 2, 28);
  h.writeUInt16LE(ch * 2, 32); h.writeUInt16LE(16, 34); h.write("data", 36); h.writeUInt32LE(data.length, 40);
  return Buffer.concat([h, data]);
}

function buildTree(root: string): void {
  // AIHub 형식 흉내: 원천데이터(소리) + 라벨링데이터(JSON). 소리는 사인파
  ["S001", "S002", "S003"].forEach((spk, k) => {
    for (let j = 1; j <= 4; j++) {
      const name = `${spk}_${String(j).padStart(4, "0")}`;
      const odd = spk === "S003" && j === 2; // 문제 파일: 44.1 kHz 스테레오
      const sr = odd ? 44100 : 16000;
      for (const sub of ["원천데이터", "라벨링데이터"]) fs.mkdirSync(path.join(root, sub, spk), { recursive: true });
      fs.writeFileSync(path.join(root, "원천데이터", spk, name + ".wav"), wavBytes(Math.floor(sr * (1 + 0.5 * j)), sr, odd ? 2 : 1, 200 + 30 * k));
      const label = { 발화정보: { stt: `${spk} 의 ${j}번째 문장입니다` }, 녹음자정보: { recorderId: spk, gender: "남", age: "30대" } };
      fs.writeFileSync(path.join(root, "라벨링데이터", spk, name + ".json"), JSON.stringify(label));
    }
  });
}

function parseLabel(jpath: string): { path: string; text: string; speaker: string } {
  // 실제 데이터에서는 이 함수만 라벨 설명서에 맞게 고친다
  const lab = JSON.parse(fs.readFileSync(jpath, "utf-8"));
  const wav = jpath.replace("라벨링데이터", "원천데이터").replace(".json", ".wav");
  return { path: wav, text: lab.발화정보.stt, speaker: lab.녹음자정보.recorderId };
}

const root = fs.mkdtempSync(path.join(os.tmpdir(), "d11man-"));
try {
  buildTree(root);
  const jsonFiles = (fs.readdirSync(path.join(root, "라벨링데이터"), { recursive: true }) as string[])
    .filter((p) => p.endsWith(".json")).map((p) => path.join(root, "라벨링데이터", p)).sort(); // 하위 폴더까지
  console.log(`JSON ${jsonFiles.length}개`);
  const rows = jsonFiles.map((jp) => {
    const r = parseLabel(jp);
    const head = fs.readFileSync(r.path).subarray(0, 44); // 소리를 다 읽지 않고 머리말만
    const ch = head.readUInt16LE(22), sr = head.readUInt32LE(24);
    return { ...r, sr, channels: ch, duration: head.readUInt32LE(40) / (ch * 2) / sr };
  });
  for (const r of rows.slice(0, 5)) {
    console.log(`${path.basename(r.path)} ${r.text} ${r.duration.toFixed(2)}초 ${r.sr}Hz ${r.channels}ch ${r.speaker}`);
  }
  const odd = rows.filter((r) => r.sr !== 16000 || r.channels !== 1).map((r) => path.basename(r.path));
  console.log("16 kHz 모노가 아닌 파일:", odd);
  check(jsonFiles.length === 12 && rows.every((r) => fs.existsSync(r.path)) && odd.length === 1 && odd[0] === "S003_0002.wav",
    "하위 폴더까지 찾아 12개를 모두 읽고 S003_0002만 형식이 달라야 해요.");
} finally {
  fs.rmSync(root, { recursive: true, force: true });
}

filter.typescript:
// D11 · Part 5 · 품질 필터 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d11_filter.ts   (표는 코드 안의 합성 목록 · 인터넷 불필요)
//   길이와 말 빠르기(초당 글자 수, CPS)로 이상한 샘플을 이유와 함께 거른다
const ROWS: [string, string, number][] = [ // 출처, 전사, 길이(초)
  ["zeroth", "오늘 날씨가 정말 좋네요", 2.5], ["zeroth", "회의는 세 시에 시작합니다", 3.0], ["kspon", "그럼 세 시에 회의를 시작할까요", 3.1],
  ["kspon", "", 2.0], ["aihub", "네", 6.0], ["aihub", "받아쓰기 모델은 위스퍼로 정했습니다", 9.0],
  ["aihub", "다음 회의에서 다시 이야기하겠습니다 자세한 내용은 그때", 1.5], ["aihub", "안녕하세요", 0.4], ["aihub", "너무 긴 녹음 파일입니다", 45.0],
];

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function judge(text: string, dur: number, maxDur: number = 30, hi: number = 12, lo: number = 2): [number, string] {
  const nChars = text.replaceAll(" ", "").length;
  const cps = nChars / dur;
  if (nChars === 0) return [cps, "빈 전사"];
  if (dur < 1.0) return [cps, "너무 짧음"];
  if (dur > maxDur) return [cps, "너무 김"];
  if (cps > hi) return [cps, "너무 빠름"];
  if (cps < lo) return [cps, "너무 느림"];
  return [cps, ""];
}

const results = ROWS.map(([src, text, dur]) => ({ src, text, dur, ...(([cps, why]) => ({ cps, why }))(judge(text, dur)) }));
const kept = results.filter((r) => !r.why);
console.log(`전체 ${results.length}개 → 남김 ${kept.length}개`);
console.log("출처".padEnd(7) + "길이".padStart(6) + "CPS".padStart(6) + "  이유 · 전사");
for (const r of results) {
  console.log(r.src.padEnd(7) + r.dur.toFixed(1).padStart(6) + r.cps.toFixed(1).padStart(6) + `  ${(r.why || "통과").padEnd(8)} ${r.text}`);
}
const reasons = new Set(results.filter((r) => r.why).map((r) => r.why));
check(["빈 전사", "너무 느림", "너무 빠름", "너무 짧음", "너무 김"].every((w) => reasons.has(w)) && kept.every((r) => r.dur <= 30),
  "빈 전사 · 너무 느림 · 너무 빠름 · 너무 짧음 · 너무 김이 모두 걸러지고, 남은 샘플은 30초 이하여야 해요.");

split.typescript:
// D11 · Part 6 · 데이터 누수: 화자 단위 분할 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d11_split.ts   (화자 12명 × 문장 10개의 합성 목록 · 인터넷 불필요)
//   문장 단위로 섞어 나누면 같은 화자가 train · test에 걸치는 것을 보이고, 화자 단위로 나눠 막는다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗을 주면 늘 같은 순서의 난수를 주는 작은 생성기
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function shuffled<T>(items: T[], rnd: () => number): T[] {
  const a = items.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rnd() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

const speakers: string[] = [];
for (let i = 0; i < 12; i++) for (let k = 0; k < 10; k++) speakers.push(`spk${String(i).padStart(2, "0")}`); // 문장 120개, 화자 12명
const idx = speakers.map((_, i) => i);
const spkOf = (part: number[]): Set<string> => new Set(part.map((i) => speakers[i]));
const inter = (a: Set<string>, b: Set<string>): string[] => [...a].filter((s) => b.has(s));

function splitBy(index: number[], testSize: number, seed: number = 0): [number[], number[]] {
  // 화자를 섞어서 test 비율만큼 화자 통째로 test로 보냄
  const spks = shuffled([...spkOf(index)].sort(), mulberry32(seed));
  const nTest = Math.max(1, Math.round(spks.length * testSize));
  const testSpk = new Set(spks.slice(0, nTest));
  return [index.filter((i) => !testSpk.has(speakers[i])), index.filter((i) => testSpk.has(speakers[i]))];
}

// 나쁜 예: 문장 단위로 무작위 분할
const sh = shuffled(idx, mulberry32(0));
const teBad = sh.slice(0, 24), trBad = sh.slice(24);
const leakBad = inter(spkOf(trBad), spkOf(teBad));
console.log(`문장 단위 분할: 겹치는 화자 ${leakBad.length}명`);

// 좋은 예: 화자 단위 분할 (test 20% → valid 15%)
const [rest, test] = splitBy(idx, 0.2);
const [train, valid] = splitBy(rest, 0.15);
for (const [name, part] of [["train", train], ["valid", valid], ["test", test]] as [string, number[]][]) {
  console.log(`${name.padEnd(5)} ${String(part.length).padStart(4)}개 · 화자 ${String(spkOf(part).size).padStart(2)}명`);
}
const overlap = [...inter(spkOf(train), spkOf(test)), ...inter(spkOf(train), spkOf(valid)), ...inter(spkOf(valid), spkOf(test))];
console.log("겹치는 화자:", overlap.length ? overlap.join(",") : "없음");
check(leakBad.length > 0 && overlap.length === 0 && train.length + valid.length + test.length === idx.length,
  "화자 ID 열로 나누면 겹치는 화자가 없어야 해요.");

features.typescript:
// D11 · Part 6 · Whisper 입력 (80 × 3000 특징 + labels) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d11_features.ts   (합성 신호 · 인터넷 불필요)
//   소리 → 로그 멜 특징(80 × 3000, 30초 창에 맞춰 채움), 글자 → labels(특수 토큰 + 글자 번호), 저장 크기까지 확인
//   흉내 낸 부분: 진짜 토크나이저(BPE) 대신 UTF-8 바이트를 글자 번호로 사용
const SR = 16000, N_FFT = 400, HOP = 160, N_MELS = 80;
const SOT = 50258, EOT = 50257, KO = 50264, TRANSCRIBE = 50359, NOTS = 50363; // Whisper 특수 토큰 번호

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function melFilters(): Float64Array[] {
  const mel = (f: number): number => 2595 * Math.log10(1 + f / 700);
  const inv = (m: number): number => 700 * (10 ** (m / 2595) - 1);
  const pts = Array.from({ length: N_MELS + 2 }, (_, i) => inv((mel(SR / 2) * i) / (N_MELS + 1)));
  return Array.from({ length: N_MELS }, (_, m) => {
    const [l, c, r] = [pts[m], pts[m + 1], pts[m + 2]];
    return Float64Array.from({ length: N_FFT / 2 + 1 }, (_, k) => {
      const hz = (k * SR) / N_FFT;
      return Math.max(0, Math.min((hz - l) / (c - l), (r - hz) / (r - c)));
    });
  });
}

function logMel(y: Float32Array): Float32Array[] {
  const half = N_FFT / 2;
  const p = new Float32Array(y.length + N_FFT); // 앞뒤로 거울처럼 덧붙임 (reflect)
  for (let i = 0; i < p.length; i++) {
    let s = i - half;
    if (s < 0) s = -s;
    if (s >= y.length) s = 2 * (y.length - 1) - s;
    p[i] = y[s];
  }
  const n = 1 + Math.floor((p.length - N_FFT) / HOP);
  const cosT = Array.from({ length: half + 1 }, (_, k) => Float64Array.from({ length: N_FFT }, (_, t) => Math.cos((2 * Math.PI * k * t) / N_FFT)));
  const sinT = Array.from({ length: half + 1 }, (_, k) => Float64Array.from({ length: N_FFT }, (_, t) => Math.sin((2 * Math.PI * k * t) / N_FFT)));
  const fb = melFilters();
  const cols: number[][] = [];
  let max = -Infinity;
  for (let i = 0; i < n; i++) {
    const seg = Float64Array.from({ length: N_FFT }, (_, t) => p[i * HOP + t] * (0.5 - 0.5 * Math.cos((2 * Math.PI * t) / N_FFT)));
    const power = new Float64Array(half + 1);
    for (let k = 0; k <= half; k++) {
      let re = 0, im = 0;
      for (let t = 0; t < N_FFT; t++) { re += seg[t] * cosT[k][t]; im -= seg[t] * sinT[k][t]; }
      power[k] = re * re + im * im;
    }
    const col = fb.map((f) => Math.log10(Math.max(f.reduce((s, w, k) => s + w * power[k], 0), 1e-10)));
    max = Math.max(max, ...col);
    cols.push(col);
  }
  // Whisper 방식: 최대값보다 8 이상 낮은 곳은 자르고 (x + 4) / 4 로 맞춤 → (80, 프레임 수)
  return Array.from({ length: N_MELS }, (_, m) => Float32Array.from(cols, (c) => (Math.max(c[m], max - 8) + 4) / 4));
}

const y = new Float32Array(Math.floor(2.5 * SR));
for (let i = 0; i < y.length; i++) y[i] = 0.3 * Math.sin((2 * Math.PI * 300 * i) / SR);
const feat = logMel(y);
const frames = feat[0].length;
let floor = Infinity;
for (const row of feat) for (const v of row) floor = Math.min(floor, v);
const padded = feat.map((row) => {
  const out = new Float32Array(3000).fill(floor); // 30초 = 3000 프레임에 맞춰 뒤를 채움
  out.set(row.subarray(0, 3000));
  return out;
});
const text = "그럼 세 시에 회의를 시작할까요";
const labels = [SOT, KO, TRANSCRIBE, NOTS, ...Buffer.from(text, "utf-8"), EOT];
console.log(`input_features 모양: (${padded.length}, ${padded[0].length}) · 실제 소리 프레임 ${frames}`);
console.log(`labels 앞 6개: ${labels.slice(0, 6).join(", ")} · 길이 ${labels.length} (Decoder 최대 448)`);
const mb = (padded.length * padded[0].length * 4) / 1e6;
console.log(`한 문장 특징 저장 크기 약 ${mb.toFixed(2)} MB → 수백 시간이면 꺼낼 때마다 만드는 방식이 필요해요`);
check(padded.length === 80 && padded[0].length === 3000 && labels.length <= 448 && Math.abs(mb - 0.96) < 0.01 && labels[0] === SOT,
  "특징은 80 × 3000, labels는 <|startoftranscript|>로 시작하고 448 이하여야 해요.");
